<?php
require_once __DIR__ . '/../user/_bootstrap.php';
require_once __DIR__ . '/../user/_layout.php';
if ($sd_user_role !== 'student') { http_response_code(403); exit('Student access only.'); }
$studentId = sd_user_student_id($conn, $sd_user_id);
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    sd_user_require_csrf();
    $action = $_POST['action'] ?? '';
    if ($action === 'club_apply') {
        sd_user_stmt($conn, 'INSERT IGNORE INTO sd_club_applications (club_id, student_id) SELECT club_id, ? FROM sd_clubs WHERE club_id = ? AND registration_open = 1 AND published = 1 AND status = "active"', 'ii', [$studentId, (int) $_POST['club_id']]);
    } elseif ($action === 'sport_apply') {
        sd_user_stmt($conn, 'INSERT IGNORE INTO sd_sport_applications (sport_id, student_id) SELECT sport_id, ? FROM sd_sports WHERE sport_id = ? AND registration_open = 1 AND published = 1 AND status = "active"', 'ii', [$studentId, (int) $_POST['sport_id']]);
    } elseif ($action === 'programme_apply') {
        $key = $_POST['programme_key'] ?? '';
        if (in_array($key, ['ncc', 'nss'], true)) { sd_user_stmt($conn, 'INSERT IGNORE INTO sd_programme_applications (programme_key, student_id) SELECT ?, ? FROM sd_programme_settings WHERE programme_key = ? AND registration_open = 1', 'sis', [$key, $studentId, $key]); }
    }
    header('Location: ' . $_SERVER['REQUEST_URI']); exit;
}
$clubCount = (int) (sd_user_rows(sd_user_stmt($conn, 'SELECT COUNT(*) total FROM sd_club_members WHERE student_id = ? AND status = "active"', 'i', [$studentId]))[0]['total'] ?? 0);
$sportCount = (int) (sd_user_rows(sd_user_stmt($conn, 'SELECT COUNT(*) total FROM sd_sport_applications WHERE student_id = ? AND status = "selected"', 'i', [$studentId]))[0]['total'] ?? 0);
$certCount = (int) (sd_user_rows(sd_user_stmt($conn, 'SELECT COUNT(*) total FROM sd_certificates WHERE student_id = ?', 'i', [$studentId]))[0]['total'] ?? 0);
$programme = sd_user_rows(sd_user_stmt($conn, 'SELECT programme_key, status FROM sd_programme_applications WHERE student_id = ? ORDER BY applied_at DESC', 'i', [$studentId]));
$clubs = sd_user_rows(sd_user_stmt($conn, 'SELECT c.name, c.category, cm.status FROM sd_club_members cm JOIN sd_clubs c ON c.club_id = cm.club_id WHERE cm.student_id = ? UNION SELECT c.name, c.category, a.status FROM sd_club_applications a JOIN sd_clubs c ON c.club_id = a.club_id WHERE a.student_id = ?', 'ii', [$studentId, $studentId]));
$availableClubs = sd_user_rows(sd_user_stmt($conn, 'SELECT c.club_id, c.name, c.category FROM sd_clubs c WHERE c.status = "active" AND c.published = 1 AND c.registration_open = 1 AND NOT EXISTS (SELECT 1 FROM sd_club_applications a WHERE a.club_id = c.club_id AND a.student_id = ?) ORDER BY c.name', 'i', [$studentId]));
$sports = sd_user_rows(sd_user_stmt($conn, 'SELECT sp.name, sp.mode, a.status, a.trial_date, a.trial_result FROM sd_sport_applications a JOIN sd_sports sp ON sp.sport_id = a.sport_id WHERE a.student_id = ? ORDER BY a.applied_at DESC', 'i', [$studentId]));
$availableSports = sd_user_rows(sd_user_stmt($conn, 'SELECT sp.sport_id, sp.name, sp.mode FROM sd_sports sp WHERE sp.status = "active" AND sp.published = 1 AND sp.registration_open = 1 AND NOT EXISTS (SELECT 1 FROM sd_sport_applications a WHERE a.sport_id = sp.sport_id AND a.student_id = ?) ORDER BY sp.name', 'i', [$studentId]));
$certificates = sd_user_rows(sd_user_stmt($conn, 'SELECT category, title, achievement_date, verification_status, reviewer_remarks FROM sd_certificates WHERE student_id = ? ORDER BY created_at DESC', 'i', [$studentId]));
$active = basename($_SERVER['SCRIPT_FILENAME'], '.php');
sd_user_header('My Development', 'Track your clubs, sports, achievements, certifications and programme participation.', $active === 'index' ? 'overview' : $active);
?>
<?php if ($active === 'index'): ?><section class="sd-user-grid"><?php foreach([[$clubCount,'Club memberships','fa-people-group','clubs.php'],[$sportCount,'Selected sports','fa-futbol','sports.php'],[$certCount,'Certificates','fa-award','achievements.php'],[count($programme),'Programme applications','fa-shield-halved','programmes.php']] as $card): ?><a class="sd-user-card" href="<?php echo $card[3]; ?>" style="text-decoration:none;color:inherit"><div class="sd-user-muted"><i class="fa-solid <?php echo $card[2]; ?>"></i> <?php echo $card[1]; ?></div><div class="sd-user-value"><?php echo $card[0]; ?></div></a><?php endforeach; ?></section><section class="sd-user-card"><h2>Quick actions</h2><p class="sd-user-muted">Use the navigation to apply for activities and review your development records.</p></section>
<?php elseif ($active === 'clubs'): ?><section class="sd-user-card sd-user-section"><h2>My clubs and applications</h2><div class="sd-user-table-wrap"><table class="sd-user-table"><thead><tr><th>Club</th><th>Category</th><th>Status</th></tr></thead><tbody><?php foreach($clubs as $item): ?><tr><td><?php echo sd_user_e($item['name']); ?></td><td><?php echo sd_user_e(ucfirst($item['category'])); ?></td><td><span class="sd-user-badge"><?php echo sd_user_e(ucfirst($item['status'])); ?></span></td></tr><?php endforeach; ?><?php if(!$clubs): ?><tr><td colspan="3">No club memberships or applications found.</td></tr><?php endif; ?></tbody></table></div><h3>Open club registrations</h3><?php foreach($availableClubs as $item): ?><form class="sd-user-toolbar" method="post"><input type="hidden" name="csrf" value="<?php echo sd_user_e(sd_user_csrf()); ?>"><input type="hidden" name="action" value="club_apply"><input type="hidden" name="club_id" value="<?php echo (int)$item['club_id']; ?>"><span><?php echo sd_user_e($item['name'].' — '.ucfirst($item['category'])); ?></span><button class="btn btn-primary">Apply</button></form><?php endforeach; ?></section>
<?php elseif ($active === 'sports'): ?><section class="sd-user-card sd-user-section"><h2>My sports participation</h2><div class="sd-user-table-wrap"><table class="sd-user-table"><thead><tr><th>Sport</th><th>Mode</th><th>Status</th><th>Trial</th></tr></thead><tbody><?php foreach($sports as $item): ?><tr><td><?php echo sd_user_e($item['name']); ?></td><td><?php echo sd_user_e(ucfirst($item['mode'])); ?></td><td><?php echo sd_user_e(ucfirst($item['status'])); ?></td><td><?php echo sd_user_e($item['trial_date'] ?: 'Not scheduled'); ?></td></tr><?php endforeach; ?><?php if(!$sports): ?><tr><td colspan="4">No sports applications found.</td></tr><?php endif; ?></tbody></table></div><h3>Open sports registrations</h3><?php foreach($availableSports as $item): ?><form class="sd-user-toolbar" method="post"><input type="hidden" name="csrf" value="<?php echo sd_user_e(sd_user_csrf()); ?>"><input type="hidden" name="action" value="sport_apply"><input type="hidden" name="sport_id" value="<?php echo (int)$item['sport_id']; ?>"><span><?php echo sd_user_e($item['name'].' — '.ucfirst($item['mode'])); ?></span><button class="btn btn-primary">Apply</button></form><?php endforeach; ?></section>
<?php elseif ($active === 'achievements'): ?><section class="sd-user-card sd-user-section"><h2>My certifications</h2><div class="sd-user-table-wrap"><table class="sd-user-table"><thead><tr><th>Type</th><th>Title</th><th>Date</th><th>Status</th><th>Remarks</th></tr></thead><tbody><?php foreach($certificates as $item): ?><tr><td><?php echo sd_user_e(ucfirst($item['category'])); ?></td><td><?php echo sd_user_e($item['title']); ?></td><td><?php echo sd_user_e($item['achievement_date']); ?></td><td><?php echo sd_user_e(ucfirst($item['verification_status'])); ?></td><td><?php echo sd_user_e($item['reviewer_remarks']); ?></td></tr><?php endforeach; ?><?php if(!$certificates): ?><tr><td colspan="5">No certifications found.</td></tr><?php endif; ?></tbody></table></div></section>
<?php else: ?><section class="sd-user-card sd-user-section"><h2>My programme applications</h2><div class="sd-user-table-wrap"><table class="sd-user-table"><thead><tr><th>Programme</th><th>Status</th></tr></thead><tbody><?php foreach($programme as $item): ?><tr><td><?php echo sd_user_e(strtoupper($item['programme_key'])); ?></td><td><span class="sd-user-badge"><?php echo sd_user_e(ucfirst($item['status'])); ?></span></td></tr><?php endforeach; ?><?php if (!$programme): ?><tr><td colspan="2">You have not applied to NCC or NSS yet.</td></tr><?php endif; ?></tbody></table></div></section><?php endif; ?>
<?php sd_user_footer(); ?>
